// ManageSingleTaskPage.js
import React, {useEffect, useState} from "react";
import {useParams, useNavigate} from "react-router-dom";

/* ============================================================
   ⭐ PRISMJS – RENKLİ KOD ÖNİZLEME
============================================================ */
import Prism from "prismjs";
import "prismjs/themes/prism-okaidia.css";
import "prismjs/components/prism-clike";
import "prismjs/components/prism-javascript";
import "prismjs/components/prism-python";
import "prismjs/components/prism-markup";
import "prismjs/components/prism-json";
import "prismjs/components/prism-markdown";

/* ============================================================
   PARTICLES (AddTaskPage ile aynı)
============================================================ */
function FloatingParticles() {
    const [particles, setParticles] = useState([]);

    useEffect(() => {
        const generated = [...Array(55)].map(() => ({
            id: crypto.randomUUID(),
            left: Math.random() * 100,
            top: Math.random() * 100,
            delay: -(Math.random() * 15).toFixed(2),
            duration: 16 + Math.random() * 10,
        }));
        setParticles(generated);
    }, []);

    return (
        <div style={styles.particles}>
            {particles.map((p) => (
                <div
                    key={p.id}
                    style={{
                        ...styles.particle,
                        left: `${p.left}%`,
                        top: `${p.top}vh`,
                        animationDelay: `${p.delay}s`,
                        animationDuration: `${p.duration}s`,
                    }}
                />
            ))}
        </div>
    );
}

/* ============================================================
   STATUS BADGES
============================================================ */
const getStyleByStatus = (status) => {
    switch ((status || "").toUpperCase()) {
        case "DRAFT":
            return {border: "#facc15", badgeBg: "rgba(250,204,21,0.15)", badgeColor: "#fde047"};
        case "ACTIVE":
            return {border: "#22c55e", badgeBg: "rgba(34,197,94,0.15)", badgeColor: "#4ade80"};
        case "COMPLETED":
            return {border: "#3b82f6", badgeBg: "rgba(59,130,246,0.15)", badgeColor: "#60a5fa"};
        case "ARCHIVED":
            return {border: "#d1d5db", badgeBg: "rgba(255,255,255,0.1)", badgeColor: "#f3f4f6"};
        default:
            return {border: "#a5b4fc", badgeBg: "rgba(165,180,252,0.15)", badgeColor: "#a5b4fc"};
    }
};

/* ============================================================
   StudyType label formatter (BUG_CATEGORIZATION → Bug Categorization)
============================================================ */
const formatStudyType = (type) => {
    if (!type) return "";
    return type
        .toLowerCase()
        .split("_")
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join(" ");
};

/* ============================================================
   PAGE
============================================================ */
function ManageSingleTaskPage() {
    const {taskId} = useParams();
    const navigate = useNavigate();

    const [task, setTask] = useState(null);
    const [loading, setLoading] = useState(true);

    const [isEditing, setIsEditing] = useState(false);
    const [editedTitle, setEditedTitle] = useState("");
    const [editedDesc, setEditedDesc] = useState("");

    const [titleError, setTitleError] = useState("");
    const [descError, setDescError] = useState("");

    const [toast, setToast] = useState(null);

    const showToast = (message, type = "success") => {
        setToast({message, type});
        setTimeout(() => setToast(null), 2000);
    };

    /* ============================================================
       🔥 LOCKED STUDY TYPES (edit kapalı)
    ============================================================ */
    const lockedStudyTypes = [
        "BUG_CATEGORIZATION",
        "CODE_CLONE",
        "SNAPSHOT_TESTING",
        "SOLID_DETECTION",
    ];
    const isLocked = task && lockedStudyTypes.includes(task.studyType);

    /* ============================================================
       ⭐ PREVIEW STATE
    ============================================================ */
    const [previewArtifact, setPreviewArtifact] = useState(null);
    const [previewURL, setPreviewURL] = useState("");
    const [previewText, setPreviewText] = useState("");
    const [previewLanguage, setPreviewLanguage] = useState("markup");
    const [previewLoading, setPreviewLoading] = useState(false);

    /* ============================================================
       ⭐ PRISM HIGHLIGHT
    ============================================================ */
    useEffect(() => {
        if (previewText) Prism.highlightAll();
    }, [previewText]);

    /* ============================================================
       LOAD TASK
    ============================================================ */
    useEffect(() => {
        const loadTask = async () => {
            try {
                const res = await fetch(`http://localhost:8080/api/tasks/details/${taskId}`);
                const data = await res.json();

                setTask(data);
                setEditedTitle(data.questionText || "");
                setEditedDesc(data.description || "");
            } catch (e) {
                showToast("Failed to load task.", "error");
            } finally {
                setLoading(false);
            }
        };

        loadTask();
    }, [taskId]);

    /* ============================================================
       SAVE CHANGES
    ============================================================ */
    const handleSave = async () => {
        if (isLocked) return showToast("This task cannot be edited for this study type.", "error");

        let err = false;

        if (editedTitle.trim().length < 5) {
            setTitleError("Title must be at least 5 characters.");
            err = true;
        } else setTitleError("");

        if (editedDesc.trim().length < 10) {
            setDescError("Description must be at least 10 characters.");
            err = true;
        } else setDescError("");

        if (err) {
            showToast("Please fix errors before saving.", "error");
            return;
        }

        try {
            const res = await fetch(`http://localhost:8080/api/tasks/update/${taskId}`, {
                method: "PUT",
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify({
                    questionText: editedTitle,
                    description: editedDesc,
                }),
            });

            if (!res.ok) throw new Error();
            const updated = await res.json();

            setTask(updated);
            setIsEditing(false);
            showToast("Task updated!", "success");
        } catch {
            showToast("Failed to update task.", "error");
        }
    };

    const handleCancelEdit = () => {
        if (!task) return;
        setEditedTitle(task.questionText);
        setEditedDesc(task.description);
        setTitleError("");
        setDescError("");
        setIsEditing(false);
    };

    /* ============================================================
       ⭐ PREVIEW HANDLER
    ============================================================ */
    const handlePreview = async (artifact) => {
        const token = localStorage.getItem("token");
        const url = `http://localhost:8080/researcher/artifact/${artifact.id}`;

        setPreviewArtifact(artifact);
        setPreviewLoading(true);
        setPreviewText("");
        setPreviewURL("");

        try {
            const response = await fetch(url, {
                headers: {Authorization: `Bearer ${token}`},
            });

            if (!response.ok) throw new Error("Preview failed");

            const blob = await response.blob();
            const blobURL = URL.createObjectURL(blob);
            const filename = artifact.filename.toLowerCase();

            if (filename.match(/\.(pdf|png|jpg|jpeg)$/i)) {
                setPreviewURL(blobURL);
            } else {
                const ext = filename.split(".").pop();
                const langMap = {
                    java: "clike",
                    js: "javascript",
                    ts: "javascript",
                    py: "python",
                    c: "clike",
                    cpp: "clike",
                    html: "markup",
                    css: "markup",
                    md: "markdown",
                    json: "json",
                    txt: "markup",
                };

                setPreviewLanguage(langMap[ext] || "markup");
                const text = await blob.text();
                setPreviewText(text);
            }
        } catch {
            setPreviewText("Preview not supported.");
        } finally {
            setPreviewLoading(false);
        }
    };

    /* ============================================================
       RENDER STATE
    ============================================================ */
    if (loading)
        return (
            <div style={{color: "#fff", textAlign: "center", marginTop: 50}}>
                Loading…
            </div>
        );
    if (!task)
        return (
            <div style={{color: "red", textAlign: "center", marginTop: 50}}>
                Task not found.
            </div>
        );

    const isDraft = task.studyStatus === "DRAFT";
    const theme = getStyleByStatus(task.studyStatus);

    const completed = task.completedParticipants || [];
    const all = task.allParticipants || [];
    const pending = all.filter((p) => !completed.some((c) => c.id === p.id));

    const percent =
        all.length === 0 ? 0 : Math.round((completed.length / all.length) * 100);

    const studyTypeLabel = task.studyType ? formatStudyType(task.studyType) : null;

    /* ============================================================
       USER CARD
    ============================================================ */
    const renderUserCard = (u, done) => {
        const first = u.username?.[0]?.toUpperCase() || "?";

        return (
            <div style={styles.userCard} key={u.id}>
                <div style={styles.userAvatar}>{first}</div>

                <div style={styles.userInfo}>
                    <div style={styles.userName}>{u.username}</div>
                    <div
                        style={{
                            ...styles.userTag,
                            color: done ? "#86efac" : "#fcd34d",
                        }}
                    >
                        {done ? "Completed" : "Pending"}
                    </div>
                </div>

                <div style={styles.userIcon}>{done ? "✔" : "⏳"}</div>
            </div>
        );
    };

    return (
        <div style={styles.container}>
            <FloatingParticles/>

            {/* TOAST (AddTaskPage tarzı üst orta) */}
            {toast && (
                <div
                    style={{
                        ...styles.toast,
                        ...(toast.type === "success"
                            ? styles.toastSuccess
                            : toast.type === "error"
                                ? styles.toastError
                                : styles.toastInfo),
                    }}
                >
                    {toast.message}
                </div>
            )}

            {/* NAVBAR */}
            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>Manage Task</h2>

                <button
                    className="back-btn"
                    style={styles.backButton}
                    onClick={() => navigate(-1)}
                >
                    ← Back
                </button>
            </div>

            {/* CONTENT */}
            <div style={styles.content}>
                <div style={styles.mainCard}>
                    {/* HEADER */}
                    <div style={styles.headerRow}>
                        <div style={{flex: 1}}>
                            <label style={styles.label}>Task Question</label>

                            {/* 🔒 Eğer studyType locked ise her zaman sadece text göster */}
                            {isLocked || !isEditing ? (
                                <h1 style={styles.taskTitle}>
                                    {task.questionText}
                                </h1>
                            ) : (
                                <>
                                    <input
                                        style={{
                                            ...styles.titleInput,
                                            borderColor: titleError
                                                ? "rgba(239,68,68,0.9)"
                                                : "rgba(96,165,250,0.5)",
                                        }}
                                        value={editedTitle}
                                        onChange={(e) => {
                                            setEditedTitle(e.target.value);
                                            if (e.target.value.length >= 5)
                                                setTitleError("");
                                        }}
                                    />
                                    {titleError && (
                                        <p style={styles.errorText}>
                                            {titleError}
                                        </p>
                                    )}
                                </>
                            )}
                        </div>

                        {/* 🔥 Study Type (sol) + Status (sağ) profesyonel layout */}
                        <div style={styles.badgeColumn}>
                            <div style={styles.badgeRow}>
                                {studyTypeLabel && (
                                    <div style={styles.badgeGroup}>
                                        <span style={styles.badgeLabel}>
                                            Study Type
                                        </span>
                                        <span style={styles.typePill}>
                                            {studyTypeLabel}
                                        </span>
                                    </div>
                                )}

                                <div style={styles.badgeGroup}>
                                    <span style={styles.badgeLabel}>
                                        Status
                                    </span>
                                    <span
                                        style={{
                                            ...styles.statusBadge,
                                            background: theme.badgeBg,
                                            color: theme.badgeColor,
                                            borderColor: theme.border,
                                        }}
                                    >
                                        {task.studyStatus}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* DESCRIPTION */}
                    <div style={styles.sectionBlock}>
                        <label style={styles.label}>Description</label>

                        {isLocked || !isEditing ? (
                            <p style={styles.descriptionText}>
                                {task.description || (
                                    <span style={{opacity: 0.6}}>
                                        No description.
                                    </span>
                                )}
                            </p>
                        ) : (
                            <>
                                <textarea
                                    rows={4}
                                    style={{
                                        ...styles.descriptionTextarea,
                                        borderColor: descError
                                            ? "rgba(239,68,68,0.9)"
                                            : "rgba(96,165,250,0.5)",
                                    }}
                                    value={editedDesc}
                                    onChange={(e) => {
                                        setEditedDesc(e.target.value);
                                        if (e.target.value.length >= 10)
                                            setDescError("");
                                    }}
                                />
                                {descError && (
                                    <p style={styles.errorText}>{descError}</p>
                                )}
                            </>
                        )}
                    </div>

                    {/* INFO ROW */}
                    <div style={styles.infoRow}>
                        <div style={styles.infoItem}>
                            <span style={styles.infoLabel}>🧩 Artifact Count:</span>
                            <span style={styles.infoValue}>
                                {task.artifactCount || 0}
                            </span>
                        </div>

                        <div style={styles.infoItem}>
                            <span style={styles.infoLabel}>👥 Participants:</span>
                            <span style={styles.infoValue}>{all.length}</span>
                        </div>
                    </div>

                    {/* EDIT BUTTONS */}
                    {!isLocked && (
                        <>
                            {!isEditing ? (
                                <button
                                    className="edit-btn"
                                    style={{
                                        ...styles.editMainButton,
                                        opacity: isDraft ? 1 : 0.4,
                                        cursor: isDraft
                                            ? "pointer"
                                            : "not-allowed",
                                    }}
                                    onClick={() => {
                                        if (!isDraft)
                                            return showToast(
                                                "This study is not in draft mode.",
                                                "error"
                                            );
                                        setIsEditing(true);
                                    }}
                                >
                                    ✏️ Edit Task Details
                                </button>
                            ) : (
                                <div style={styles.editActions}>
                                    <button
                                        className="save-btn"
                                        style={styles.saveButton}
                                        onClick={handleSave}
                                    >
                                        💾 Save Changes
                                    </button>

                                    <button
                                        className="cancel-btn"
                                        style={styles.cancelButton}
                                        onClick={handleCancelEdit}
                                    >
                                        ✕ Cancel
                                    </button>
                                </div>
                            )}
                        </>
                    )}

                    {/* ================= ARTIFACTS ================= */}
                    <div style={styles.sectionBlock}>
                        <div style={styles.sectionHeaderRow}>
                            <div>
                                <h3 style={styles.sectionTitle}>
                                    Artifacts Linked to This Task
                                </h3>
                                <p style={styles.sectionDescription}>
                                    These artifacts will be shown to
                                    participants.
                                </p>
                            </div>

                            <button
                                className="manage-btn"
                                style={{
                                    ...styles.manageArtifactsButton,
                                    opacity: isDraft ? 1 : 0.4,
                                    cursor: isDraft
                                        ? "pointer"
                                        : "not-allowed",
                                }}
                                onClick={() => {
                                    if (!isDraft)
                                        return showToast(
                                            "This study is not in draft mode.",
                                            "error"
                                        );
                                    navigate(`/manage-artifacts/${task.id}`);
                                }}
                            >
                                ⚙️ Manage Artifacts
                            </button>
                        </div>

                        <div style={styles.artifactList}>
                            {task.artifacts?.length ? (
                                task.artifacts.map((a) => {
                                    const ext =
                                        a.filename
                                            ?.split(".")
                                            .pop()
                                            ?.toLowerCase() || "file";

                                    return (
                                        <div
                                            key={a.id}
                                            style={styles.artifactCard}
                                        >
                                            <div style={styles.artifactHeader}>
                                                {/* 🔹 ARTEFACT NAME */}
                                                <p style={styles.artifactName}>
                                                    {a.filename}
                                                </p>

                                                {/* 🔹 BADGES */}
                                                <div style={styles.artifactBadges}>
                                                    {/* CATEGORY BADGE */}
                                                    <span style={styles.typeBadge}>
                                                    {a.category ? a.category : "No Category"}
                                                </span>

                                                    {/* TAG BADGE */}
                                                    <span style={styles.tagBadge}>
                                                    {a.tags ? a.tags : "No Tag"}
                                                </span>
                                                </div>


                                                {/* 🔥 GÖZ BUTONU */}
                                                <div
                                                    className="eye-hover"
                                                    onClick={() =>
                                                        handlePreview(a)
                                                    }
                                                    style={styles.eyeButton}
                                                >
                                                    <svg
                                                        width="20"
                                                        height="20"
                                                        viewBox="0 0 24 24"
                                                        fill="none"
                                                        stroke="#60a5fa"
                                                        strokeWidth="2"
                                                        strokeLinecap="round"
                                                        strokeLinejoin="round"
                                                    >
                                                        <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                                                        <circle
                                                            cx="12"
                                                            cy="12"
                                                            r="3"
                                                        ></circle>
                                                    </svg>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })
                            ) : (
                                <p style={styles.noCriteria}>
                                    No artifacts linked to this task.
                                </p>
                            )}
                        </div>
                    </div>

                    {/* ================= CORRECT ANSWER ================= */}
                    {task.studyType !== "CUSTOM" && (
                        <div style={styles.sectionBlock}>

                            {/* HEADER ROW (Artifacts ile aynı düzen) */}
                            <div style={styles.sectionHeaderRow}>
                                <div>
                                    <h3 style={styles.sectionTitle}>Correct Answer</h3>
                                    <p style={styles.sectionDescription}>
                                        The correct reference answer for this task.
                                    </p>
                                </div>

                                <button
                                    className="manage-btn"
                                    style={{
                                        ...styles.manageArtifactsButton,
                                        opacity: isDraft ? 1 : 0.4,
                                        cursor: isDraft ? "pointer" : "not-allowed",
                                    }}
                                    onClick={() => {
                                        if (!isDraft)
                                            return showToast("This study is not in draft mode.", "error");
                                        navigate(`/manage-correct-answer/${task.id}`);
                                    }}
                                >
                                    🧠 Manage Correct Answer
                                </button>
                            </div>

                            {/* Hiçbiri gelmediyse fallback */}
                            {!task.bugCorrectAnswer &&
                                !task.cloneCorrectAnswer &&
                                !task.snapshotCorrectAnswer &&
                                !task.solidCorrectAnswer && (
                                    <p style={styles.noCriteria}>
                                        No correct answer is defined for this task.
                                    </p>
                                )}

                            {/* --- BUG CATEGORIZATION --- */}
                            {task.studyType === "BUG_CATEGORIZATION" &&
                                task.bugCorrectAnswer && (
                                    <div style={styles.answerGrid}>
                                        {Object.entries(task.bugCorrectAnswer).map(
                                            ([key, value]) => {
                                                if (key === "id") return null;
                                                return (
                                                    <div
                                                        key={key}
                                                        style={{
                                                            padding: "10px 14px",
                                                            borderRadius: 10,
                                                            border:
                                                                "1px solid rgba(96,165,250,0.35)",
                                                            background: value
                                                                ? "rgba(34,197,94,0.25)"
                                                                : "rgba(15,23,42,0.7)",
                                                            color: value
                                                                ? "#bbf7d0"
                                                                : "#e5e7eb",
                                                            fontWeight: 600,
                                                            textTransform: "capitalize",
                                                        }}
                                                    >
                                                        {key.replace(/([A-Z])/g, " $1")}
                                                    </div>
                                                );
                                            }
                                        )}
                                    </div>
                                )}

                            {/* --- CODE CLONE --- */}
                            {task.studyType === "CODE_CLONE" &&
                                task.cloneCorrectAnswer && (
                                    <div style={styles.answerGrid}>
                                        {[
                                            { key: "type1", label: "Type-1 (Exact clone)" },
                                            { key: "type2", label: "Type-2 (Renamed / formatting)" },
                                            { key: "type3", label: "Type-3 (Modified)" },
                                            { key: "type4", label: "Type-4 (Semantic clone)" },
                                            { key: "notClone", label: "Not Clone (No similarity)" },

                                        ].map((t) => {
                                            const val = task.cloneCorrectAnswer[t.key];
                                            return (
                                                <div
                                                    key={t.key}
                                                    style={{
                                                        padding: "10px 14px",
                                                        borderRadius: 10,
                                                        border:
                                                            "1px solid rgba(96,165,250,0.35)",
                                                        background: val
                                                            ? "rgba(34,197,94,0.25)"
                                                            : "rgba(15,23,42,0.7)",
                                                        color: val ? "#bbf7d0" : "#e5e7eb",
                                                        fontWeight: 600,
                                                    }}
                                                >
                                                    {t.label}
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}

                            {/* --- SNAPSHOT TESTING --- */}
                            {task.studyType === "SNAPSHOT_TESTING" &&
                                task.snapshotCorrectAnswer && (
                                    <div style={styles.answerGrid}>
                                        {[
                                            "colorChange",
                                            "shapeChange",
                                            "positionChange",
                                            "layoutChange",
                                            "visibilityChange",
                                            "fontChange",
                                            "contentChange",
                                            "sizeChange",
                                            "unknownChange",
                                        ].map((k) => {
                                            const val = task.snapshotCorrectAnswer[k];
                                            return (
                                                <div
                                                    key={k}
                                                    style={{
                                                        padding: "10px 14px",
                                                        borderRadius: 10,
                                                        border:
                                                            "1px solid rgba(96,165,250,0.35)",
                                                        background: val
                                                            ? "rgba(56,189,248,0.25)"
                                                            : "rgba(15,23,42,0.7)",
                                                        color: val ? "#bae6fd" : "#e5e7eb",
                                                        fontWeight: 600,
                                                        textTransform: "capitalize",
                                                    }}
                                                >
                                                    {k.replace(/([A-Z])/g, " $1")}
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}

                            {/* --- SOLID DETECTION --- */}
                            {task.studyType === "SOLID_DETECTION" &&
                                task.solidCorrectAnswer && (
                                    <div style={styles.answerGrid}>
                                        {/* Principles */}
                                        <h4 style={{ marginBottom: 6, color: "#93c5fd" }}>
                                            Violated Principles
                                        </h4>
                                        {["srp", "ocp", "lsp", "isp", "dip"].map((p) => {
                                            const val = task.solidCorrectAnswer[p];
                                            return (
                                                <div
                                                    key={p}
                                                    style={{
                                                        padding: "10px 14px",
                                                        borderRadius: 10,
                                                        border:
                                                            "1px solid rgba(96,165,250,0.35)",
                                                        background: val
                                                            ? "rgba(34,197,94,0.25)"
                                                            : "rgba(15,23,42,0.7)",
                                                        color: val ? "#bbf7d0" : "#e5e7eb",
                                                        fontWeight: 600,
                                                        textTransform: "uppercase",
                                                    }}
                                                >
                                                    {p}
                                                </div>
                                            );
                                        })}

                                        {/* Difficulty */}
                                        <h4
                                            style={{
                                                marginTop: 10,
                                                marginBottom: 6,
                                                color: "#93c5fd",
                                            }}
                                        >
                                            Difficulty
                                        </h4>

                                        {["easy", "medium", "hard"].map((d) => {
                                            const val = task.solidCorrectAnswer[d];
                                            return (
                                                <div
                                                    key={d}
                                                    style={{
                                                        padding: "10px 14px",
                                                        borderRadius: 10,
                                                        border:
                                                            "1px solid rgba(96,165,250,0.35)",
                                                        background: val
                                                            ? "rgba(234,179,8,0.25)"
                                                            : "rgba(15,23,42,0.7)",
                                                        color: val ? "#fde047" : "#e5e7eb",
                                                        fontWeight: 600,
                                                        textTransform: "capitalize",
                                                    }}
                                                >
                                                    {d}
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                        </div>
                    )}


                    {/* ================= CRITERIA ================= */}
                    <div style={styles.sectionBlock}>
                        <h3 style={styles.sectionTitle}>Criteria Used</h3>

                        {task.evaluationCriteria?.length ? (
                            <div style={styles.criteriaCardContainer}>
                                {task.evaluationCriteria.map((c, i) => (
                                    <div key={i} style={styles.criteriaCard}>
                                        <h4 style={styles.criteriaTitle}>
                                            {c.name}
                                        </h4>
                                        {c.description && (
                                            <p
                                                style={
                                                    styles.criteriaDescription
                                                }
                                            >
                                                {c.description}
                                            </p>
                                        )}

                                        <div style={styles.criteriaMeta}>
                                            <span style={styles.metaBadge}>
                                                Scale: {c.scaleType}
                                            </span>
                                            {c.scaleRange && (
                                                <span style={styles.metaBadge}>
                                                    Range: {c.scaleRange}
                                                </span>
                                            )}
                                            <span style={styles.metaBadge}>
                                                Priority: {c.priorityOrder}
                                            </span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <p style={styles.noCriteria}>
                                This study has no criteria for this task.
                            </p>
                        )}
                    </div>

                    {/* ================= PARTICIPANTS ================= */}
                    <div style={styles.sectionBlock}>
                        <h3 style={styles.sectionTitle}>Participants</h3>

                        <div style={styles.progressContainer}>
                            <div style={styles.progressLabel}>
                                {completed.length} / {all.length} completed (
                                {percent}%)
                            </div>

                            <div style={styles.progressBarBackground}>
                                <div
                                    style={{
                                        ...styles.progressBarFill,
                                        width: `${percent}%`,
                                    }}
                                />
                            </div>
                        </div>

                        <div style={styles.participantWrapper}>
                            <div style={styles.participantColumn}>
                                <h4 style={styles.participantColumnTitle}>
                                    ✔ Completed
                                </h4>

                                <div style={styles.participantBox}>
                                    {completed.length ? (
                                        completed.map((p) =>
                                            renderUserCard(p, true)
                                        )
                                    ) : (
                                        <p style={styles.noCriteria}>
                                            No completed participants.
                                        </p>
                                    )}
                                </div>
                            </div>

                            <div style={styles.participantColumn}>
                                <h4 style={styles.participantColumnTitle}>
                                    ⏳ Pending
                                </h4>

                                <div style={styles.participantBox}>
                                    {pending.length ? (
                                        pending.map((p) =>
                                            renderUserCard(p, false)
                                        )
                                    ) : (
                                        <p style={styles.noCriteria}>
                                            No pending participants.
                                        </p>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* ================= DELETE TASK (UI ONLY — NO API) ================= */}
                    <div style={styles.sectionBlock}>
                        <h3 style={styles.deleteTitle}>Danger Zone</h3>
                        <p style={styles.deleteDescription}>
                            Deleting a task will permanently remove it from this study.
                            This action cannot be undone.
                        </p>

                        <button
                            className="delete-btn"
                            data-active={task.studyStatus === "DRAFT"}
                            style={{
                                ...styles.deleteButton,
                                ...(task.studyStatus !== "DRAFT" ? styles.deleteDisabled : {}),
                            }}
                            onClick={() => {
                                if (task.studyStatus !== "DRAFT") {
                                    return showToast(
                                        "❗ You can delete a task only when the study is in DRAFT mode.",
                                        "error"
                                    );
                                }
                                showToast("Delete Task is not implemented yet.", "error");
                            }}
                        >
                            🗑️ Delete This Task
                        </button>


                    </div>

                </div>
            </div>

            {/* =================== PREVIEW MODAL =================== */}
            {previewArtifact && (
                <div
                    style={styles.modalOverlay}
                    onClick={() => setPreviewArtifact(null)}
                >
                    <div
                        style={styles.modalContent}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <h2 style={styles.previewTitle}>
                            {previewArtifact.filename}
                        </h2>

                        {previewLoading ? (
                            <p style={{color: "#93c5fd"}}>Loading preview...</p>
                        ) : (
                            <>
                                {/* PDF */}
                                {previewURL &&
                                    previewArtifact.filename.endsWith(
                                        ".pdf"
                                    ) && (
                                        <embed
                                            src={previewURL}
                                            type="application/pdf"
                                            style={styles.previewPDF}
                                        />
                                    )}

                                {/* Image */}
                                {previewURL &&
                                    previewArtifact.filename.match(
                                        /\.(png|jpg|jpeg)$/i
                                    ) && (
                                        <img
                                            src={previewURL}
                                            alt="preview"
                                            style={styles.previewImage}
                                        />
                                    )}

                                {/* Code / Text */}
                                {previewText && (
                                    <pre style={styles.previewPre}>
                                        <code
                                            className={`language-${previewLanguage}`}
                                        >
                                            {previewText}
                                        </code>
                                    </pre>
                                )}
                            </>
                        )}

                        <button
                            className="close-btn"
                            onClick={() => setPreviewArtifact(null)}
                            style={styles.closeButton}
                        >
                            Close
                        </button>
                    </div>
                </div>
            )}

            {/* KEYFRAMES */}
            <style>
                {`
                    @keyframes floatParticle {
                        0% { transform: translateY(0); opacity: .4; }
                        50% { opacity: 1; }
                        100% { transform: translateY(-120vh); opacity: 0; }
                    }

                    @keyframes toastFade {
                        0% { opacity: 0; transform: translateX(-50%) translateY(-6px); }
                        100% { opacity: 1; transform: translateX(-50%) translateY(0); }
                    }
                `}
            </style>
        </div>
    );
}

/* ============================================================
   STYLES (AddTaskPage tarzı güncellendi)
============================================================ */
const styles = {
    container: {
        minHeight: "100vh",
        background: "linear-gradient(135deg, #0a0a0a, #16213e)",
        color: "#fff",
        fontFamily: "Inter, sans-serif",
        paddingBottom: "60px",
        position: "relative",
        overflow: "hidden",
    },

    /* PARTICLES */
    particles: {
        position: "fixed",
        inset: 0,
        pointerEvents: "none",
        zIndex: 0,
    },

    particle: {
        position: "absolute",
        width: "4px",
        height: "4px",
        background: "linear-gradient(135deg, #06b6d4, #8b5cf6)",
        borderRadius: "50%",
        animation: "floatParticle linear infinite",
        opacity: 0.45,
    },

    toast: {
        position: "fixed",
        top: "20px",
        left: "50%",
        background: "rgba(30,30,30,0.92)",
        padding: "14px 28px",
        borderRadius: "10px",
        color: "white",
        fontSize: "1rem",
        fontWeight: "600",
        border: "1px solid rgba(255,255,255,0.12)",
        boxShadow: "0 6px 18px rgba(0,0,0,0.45)",
        animation: "toastFade 0.35s ease-out",
        backdropFilter: "blur(6px)",
        zIndex: 9999,
        transform: "translateX(-50%)",
    },
    toastSuccess: {
        background: "rgba(34,197,94,0.22)",
        border: "1px solid rgba(34,197,94,0.55)",
        boxShadow: "0 0 14px rgba(34,197,94,0.45)",
        color: "#bbf7d0",
    },
    toastError: {
